--region init
function ActivityMidFestivalRecordDialog:InitHandler()
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnFightClickHandler))
    SetButtonAction(self.FontStyleButtonSweep, Bind(self, self.OnBtnSweepHandler))
    ---@type CommonBtnConsumePop
    self._consumePopScr = CfUtils.GetLuaScr(self.CommonBtnConsumePop, "Game.UI.Common.CommonBtnConsumePop")
    self.events[Constants.EventNames.MidFestivalRegionRewardsRefresh] = Events.AddListener(Constants.EventNames.MidFestivalRegionRewardsRefresh, Bind(self, self.RefreshBtnFight))
    self.events[Constants.EventNames.MidFestivalRecordRewardReq] = Events.AddListener(Constants.EventNames.MidFestivalRecordRewardReq, Bind(self, self.RefreshRewards))
    self.events[Constants.EventNames.EveryThingChangeEventName] = Events.AddListener(Constants.EventNames.EveryThingChangeEventName, Bind(self, self.BuyCallback))
end

function ActivityMidFestivalRecordDialog:InitData()
    self._homeDojo = self._activityMidFestivalComponent:GetHomeDojo()
    self.repaintingQuestHash = self._homeDojo.repaintingQuestHash
    self.questVoList = self:GetQuestVoList()
    self.rewardsVo = CfUtils.GetCf(AutoIds.IdSetting6080, "MidFestivalReChallengeRewardVo", true)

    self:RefreshUI()
end

function ActivityMidFestivalRecordDialog:GetQuestVoList()
    local allVos = CfUtils.GetCf(AutoIds.IdSetting6079, "MidFestivalReChallengeLevelVo", true)
    local activityContentId = self._activityMidFestivalComponent:GetActivityDojo().activityContentId
    local data = {}
    for i, v in ipairs(allVos) do
        if v.activityId == activityContentId then
            table.insert(data,v)
        end
    end
    return data
end
--endregion init

--region handler
function ActivityMidFestivalRecordDialog:BuyCallback()
    if isNotNull(self._curSelectQuestVo) then
        ---@type number @ 0未解锁 1已解锁 2已通关
        local status = checkNumber(self.repaintingQuestHash[checkString(self._curSelectQuestVo.id)].status)
        local isMainLock = status == Constants.MidFestivalRecordStatus.MAIN_LOCK
        local isRecordLock = status == Constants.MidFestivalRecordStatus.RECORD_LOCK
        self:RefreshBtnFight(self._curSelectQuestVo, isMainLock, isRecordLock)
    end
end

function ActivityMidFestivalRecordDialog:OnBtnFightClickHandler()
    -- 检查主线关卡是否解锁
    if checkBool(self._isMainLock) then
        local unlockLevel = checkNumber(self._curSelectQuestVo.mainQuestUnlockLevel)
        local curMainLevel = checkNumber(self._homeDojo.mainQuestId)
        if curMainLevel < unlockLevel then
            ---@type MidFestivalMainQuestLevelVo
            local mainQuestVo = CfUtils.GetCfVo(AutoIds.IdSetting6086, "MidFestivalMainQuestLevelVo", unlockLevel)
            local unlockLevelName = ""
            if mainQuestVo then
                unlockLevelName = mainQuestVo.name
            end
            GameUtils.Toast(localize("通关追踪事件_name_后解锁", {_name_ = unlockLevelName}))
            return
        end
    end

    -- 检查线性关卡是否通关
    if checkBool(self._isRecordLock) then
        GameUtils.Toast(localize("通关上一个关卡后解锁"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UIFightTeamChoose, parameters = { levelId = self._curSelectQuestVo.id, activityUuid = self._activityMidFestivalComponent:GetActivityDojo().id } }, {
        { id = self.controller.Argument.id },
    })
end

function ActivityMidFestivalRecordDialog:OnBtnSweepHandler()
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local isPass = activityComp:GetHomeDojo():IsRecordQuestPass(self._curSelectQuestVo.id)
    if isPass then
        UIModule.OpenDialog({ id = Constants.UITypeIds.UISweepPrepareDialog, parameters = { questId = self._curSelectQuestVo.id, activityUuid = activityComp:GetActivityDojo().id } })
    else
        GameUtils.Toast(localize("首次通关后解锁扫荡"))
    end
end
--endregion handler

--region private
---@param cellVo MidFestivalReChallengeLevelVo
function ActivityMidFestivalRecordDialog:RefreshBtnFight(cellVo, isMainLock, isRecordLock)
    local isLock = checkBool(isMainLock) or checkBool(isRecordLock)
    self._isMainLock = checkBool(isMainLock)
    self._isRecordLock = checkBool(isRecordLock)
    CfUtils.SetActive(self.FontStyleButton, true)
    CfUtils.SetActive(self.CommonBtnConsumePop, not isLock)
    CfUtils.SetActive(self.RewardNode, not isLock)
    if isLock then
        CfUtils.FillText(self.Text, localize("未开启"))
        self.FontStyleButton:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B18")
        return
    end

    self.FontStyleButton:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B6")

    CfUtils.FillText(self.Text, localize("前往战斗"))
    self._consumePopScr:RefreshUI(cellVo.costItem, cellVo.costNum)
end

function ActivityMidFestivalRecordDialog:RefreshItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self.questVoList[luaIndex]
    ---@type number @ 0未解锁 1已解锁 2已通关
    local status = checkNumber(self.repaintingQuestHash[checkString(cellData.id)].status)
    local cell = listView:NewListViewItem("Cell")
    ---@type ActivityMidFestivalRecordRegionCell
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.MidFestival.RecordDialog.ActivityMidFestivalRecordRegionCell")
    scr:Refresh(cellData, status)
    scr:SetClickCallback(function()
        ---@type MidFestivalReChallengeLevelVo
        self._curSelectQuestVo = cellData
        self:RefreshBtnSweep()
    end)
    if checkNumber(self.showIndex) == luaIndex then
        scr:OnClickHandler()
    end
    return cell
end

function ActivityMidFestivalRecordDialog:RefreshRegions()
    local length = table.count(self.questVoList)

    self.showIndex = 0
    for index, quest in ipairs(self._homeDojo.repaintingQuest) do
        if quest.status == Constants.MidFestivalRecordStatus.UNLOCK then
            self.showIndex = index
        end
    end

    if self.RegionItem.IsListViewInit then
        GameUtils.ReloadData(self.RegionItem, length)
    else
        self.RegionItem:InitListView(length, Bind(self, self.RefreshItemByIndex))
    end
    self.RegionItem:MovePanelToItemIndex(self.showIndex-1)
end

function ActivityMidFestivalRecordDialog:RefreshPictures()
    for i, v in ipairs(self.questVoList) do
        local cellData = v
        ---@type number @ 0未解锁 1已解锁 2已通关
        local status = checkNumber(self.repaintingQuestHash[checkString(cellData.id)].status)
        if status == 0 then
            local point = self.BgNode.transform:Find("ImagePoint" .. i)
            if isNotNull(point) then
                CfUtils.SetActive(self.BgNode.transform:Find("ImagePoint" .. i), false)
            end
        end
    end
end

function ActivityMidFestivalRecordDialog:RefreshUI()
    self:RefreshRegions()
    self:RefreshPictures()
end

function ActivityMidFestivalRecordDialog:RefreshRewards(regionId)
    ---@type MidFestivalReChallengeRewardVo
    local rewardVo = CfUtils.GetCfVo(AutoIds.IdSetting6080, "MidFestivalReChallengeRewardVo", checkNumber(regionId))

    if isNull(rewardVo) then
        return
    end

    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local isPass = activityComp:GetHomeDojo():IsRecordQuestPass(regionId)
    self.config:Set(CONFIG.IS_QUEST_PASS, isPass)

    local rewards = {}

    for i = 1, #rewardVo.showItem do
        local rewardType = checkNumber(rewardVo.showItemTag[i])
        self.config:Set(CONFIG.IS_FirstPass_REWARD, rewardType == Constants.RewardSourceType.FirstPass)
        local reward = {
            ["id"] = checkNumber(rewardVo.showItem[i]),
            ["num"] = checkNumber(rewardVo.showItemNum[i]),
            ["type"] = rewardType,
            ["isGet"] = self.config:Get(CONFIG.IS_FirstPass_REWARD) and self.config:Get(CONFIG.IS_QUEST_PASS)
        }
        table.insert(rewards, reward)
    end

    ---@type CommonGoodsList
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, "Game.Behaviours.CommonGoodsList")
    scr:FreshBaseUI(rewards)
end

function ActivityMidFestivalRecordDialog:RefreshBtnSweep()
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)
    local isPass = activityComp:GetHomeDojo():IsRecordQuestPass(self._curSelectQuestVo.id)
    if not isPass then
        self.FontStyleButtonSweep:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B18")
    else
        self.FontStyleButtonSweep:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B7")
    end

end
